<template>
  <section ref="desk" class="research-desk" :class="{ 'is-research': advanced }" aria-label="问数业务过程">
    <header v-if="advanced" class="desk-heading">
      <div><span class="eyebrow">{{ advanced ? 'INVESTIGATION / 02' : 'QUERY / 01' }}</span><h2>{{ advanced ? '研究工作台' : '本次查询依据' }}</h2></div>
      <span aria-live="polite" class="task-state" :class="outcome.status">{{ stateLabel }}</span>
    </header>
    <div v-if="advanced" class="scope-line"><span class="scope-lock">◇</span>当前账号授权组织<span>{{ advanced ? '主理人规划 · 专家取证 · 证据复核' : '口径确认 · 查询核验 · 返回事实' }}</span></div>

    <section v-if="!advanced" class="query-journey" :class="outcome.status" aria-label="本次查询进展">
      <header><div><h2>本次查询依据</h2><span class="journey-state" role="status" aria-live="polite">{{ outcome.label }}</span></div><button v-if="allowInspector" @click="$emit('inspect', latestPhase)">查看分析过程 ↗</button></header>
      <nav class="journey-phases" aria-label="本次查询阶段"><button v-for="phase in phases" :key="phase.id" :class="phase.status" :disabled="!allowInspector" @click="$emit('inspect',phase.id)"><span>{{ phase.status==='completed'?'✓':phase.status==='running'?'◌':phase.status==='warning'?'!':String(phase.id+1).padStart(2,'0') }}</span><strong>{{ phase.title }}</strong><small>{{ phase.status==='planned'?'未开始':phase.status==='unrecorded'?'未单独记录':phase.status==='running'?'进行中':phase.status==='warning'?'需关注':'已完成' }}</small></button></nav>
      <details class="journey-evidence" :open="active || ['failed','partial'].includes(outcome.status)">
        <summary><span>问题范围 · 查询方案 · 审核与返回数据</span><span class="evidence-open-label">查看六项依据<svg viewBox="0 0 16 16" fill="none" aria-hidden="true"><path d="m6 3 5 5-5 5" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round"/></svg></span></summary>
        <AnalysisBrief :workflow="workflow" :result="result" :busy="active" />
      </details>
      <footer><p>{{ outcome.description }}</p><button v-if="['failed','partial'].includes(outcome.status) && allowRetry" @click="$emit('retry')">重新编辑问题 ↗</button></footer>
    </section>
    <div v-if="advanced" class="research-lifecycle" aria-label="研究阶段"><div v-for="(step,index) in lifecycle" :key="step.name" :class="step.state"><span>{{ String(index+1).padStart(2,'0') }}</span><strong>{{ step.name }}</strong><small>{{ step.label }}</small></div></div>

    <AnalysisBrief v-if="advanced" :workflow="workflow" :result="result" :busy="active" />
    <div v-if="advanced && active" class="live-observatory" role="status" aria-live="polite"><span class="observatory-orbit" aria-hidden="true">◌</span><div><small>{{ advanced?'研究正在推进':'正在理解与核验' }}</small><strong>{{ nodes.at(-1)?.title || '正在等待服务返回执行记录' }}</strong><p>{{ nodes.at(-1)?.summary || '收到真实执行事件后，这里会同步更新。' }}</p></div><span>{{ nodes.length }} 项执行记录</span></div>
    <nav v-if="advanced" class="research-nav" aria-label="研究目录"><button v-for="[key,name] in [['research-plan','研究计划'],['investigation','并行调查'],['research-report','研究报告'],['execution-record','执行记录']]" :key="key" type="button" @click="navigate(key)">{{ name }}</button></nav>
    <details v-if="advanced && plan" class="research-plan" :open="waiting">
      <summary class="section-heading"><h3>{{ waiting ? '先审阅研究计划' : '本次研究范围' }}</h3><small>主理人 · {{ plan.branches?.length || 0 }} 个验证方向</small></summary>
      <div class="plan-cover"><span>RESEARCH BRIEF</span><p class="plan-question">{{ plan.question }}</p><div class="plan-cover-meta"><span>{{ plan.branches?.length || 0 }} 个研究方向</span><span>最多 {{ plan.limits?.maxParallel || 3 }} 路并行</span><span>先确认，再执行</span></div></div>
      <p v-if="waiting" class="muted">保留需要的方向，再开始取证。计划阶段只读取资产信息，尚未执行取证 SQL。</p>
      <div class="plan-branches">
        <label v-for="(branch, index) in plan.branches" :key="branch.id" class="plan-branch" :class="{ excluded: waiting && !selected.includes(branch.id) }">
          <input v-if="waiting && !readonly" v-model="selected" type="checkbox" :value="branch.id" :disabled="busy" />
          <span v-else class="branch-index">{{ String(index + 1).padStart(2,'0') }}</span>
          <span><strong>{{ branch.title }}</strong><span class="branch-description">{{ branch.hypothesis }}</span><small>{{ branch.question }}</small></span>
        </label>
      </div>
      <div v-if="waiting && !readonly" class="plan-actions"><span>已选 {{ selected.length }} 项 · 并发上限 {{ plan.limits?.maxParallel || 3 }}</span><button type="button" class="primary" :disabled="busy || !selected.length" @click="$emit('start-plan', selected)">{{ busy ? '正在启动…' : '确认计划，开始取证' }}</button></div>
    </details>

    <div v-if="advanced && lanes.length && !waiting" class="investigation">
      <div class="section-heading"><h3>并行调查</h3><small>{{ evidence.length }} / {{ lanes.length }} 个方向已返回</small></div>
      <div class="fanout"><span>主理人分发</span><i></i><span>领域专家并行取证</span></div>
      <div class="lane-grid">
        <article v-for="branch in lanes" :key="branch.id" class="investigation-lane" :class="branchStatus(branch.id)">
          <div class="lane-top"><span>验证方向</span><span class="lane-state">{{ labelFor(branchStatus(branch.id)) }}</span></div>
          <h4>{{ branch.title }}</h4><p>{{ branch.hypothesis }}</p>
          <template v-if="branchEvidence(branch.id)"><div class="finding"><span>证据发现</span><p>{{ branchEvidence(branch.id).finding }}</p><strong v-if="branchEvidence(branch.id).row_count">{{ branchEvidence(branch.id).row_count }} <small>行结果</small></strong></div><button type="button" class="text-action" @click="openEvidence(branch.id)">查看依据与数据 ↗</button></template>
          <p v-else class="lane-activity"><span v-if="active && branchStatus(branch.id) === 'running'" class="activity-dot"></span>{{ latestBranchActivity(branch.id) }}</p>
          <div v-if="branchNodes(branch.id).some(n => n.node_id === 'R26')" class="repair-note">↻ 已触发修复，修复后重新审核与注入权限</div>
        </article>
      </div>
    </div>

    <section v-if="advanced && result?.research" class="research-report">
      <div class="section-heading"><h3>研究报告</h3><button v-if="allowDownload" type="button" class="text-action" @click="$emit('download-report')">下载研究报告 ↗</button><span :class="{ 'gap-label': result.research.partial }">{{ result.research.partial ? '含待补证方向' : '已汇合可用证据' }}</span></div>
      <header class="research-report-cover"><span>DATAPULSE / RESEARCH NOTE</span><h2>{{ result.question || plan?.question }}</h2><div><span>{{ evidence.length }} 项分支返回</span><span>{{ result.research.gaps?.length || 0 }} 项待补证</span><span>仅依据本次查询证据</span></div></header>
      <div class="evidence-compass" aria-label="证据聚焦导航"><div class="compass-heading"><span>EVIDENCE COMPASS</span><small>选择方向，聚焦下方证据画布 · 摘要保留完整研究结论</small></div><div class="compass-options"><button :aria-pressed="!evidenceFocus" @click="evidenceFocus=''">全部方向 <small>{{ evidence.length }}</small></button><button v-for="(entry,index) in evidence" :key="entry.id" :aria-pressed="evidenceFocus===entry.id" @click="evidenceFocus=evidenceFocus===entry.id?'':entry.id"><span class="compass-number">{{ String(index+1).padStart(2,'0') }}</span>{{ entry.title }}<span class="compass-state" :class="entry.status">{{ labelFor(entry.status) }}</span></button></div></div>
      <nav class="report-view-tabs" aria-label="研究报告视图"><button v-for="[key,label] in [['summary','结论摘要'],['evidence','证据索引'],['limits','边界与待补证']]" :key="key" :aria-pressed="reportTab===key" @click="reportTab=key">{{ label }}</button></nav>
      <div v-show="reportTab==='summary'">
      <div v-if="result.research.summary" class="research-summary"><p>{{ result.research.summary.conclusion }}</p><div v-for="(finding, index) in result.research.summary.findings" :key="index"><p>{{ finding.text }}</p><button v-for="id in finding.evidence_ids" :key="id" type="button" class="text-action" @click="openEvidence(id)">{{ laneName(id) }} ↗</button></div></div>
      <p class="report-boundary">{{ result.research.boundary }}</p>
      </div>
      <div v-show="reportTab==='evidence'" class="evidence-index"><div class="evidence-index-head"><span>验证方向</span><span>返回状态</span><span>取证结果</span></div><button v-for="entry in result.research.evidence" :key="entry.id" @click="openEvidence(entry.id)"><strong>{{ entry.title }}</strong><span>{{ labelFor(entry.status) }}</span><span>{{ entry.finding }}</span></button></div>
      <div v-show="reportTab==='limits'" class="report-limits"><h4>结论适用范围</h4><p>{{ result.research.boundary }}</p><p v-for="(limit,index) in result.research.summary?.limitations || []" :key="index">{{ limit }}</p><h4>仍需补充的证据</h4><p>{{ result.research.gaps?.length ? result.research.gaps.join('、') : '本次未返回额外缺口；这不等同于已完成因果证明。' }}</p></div>
      <div v-if="evidenceFocus" class="focus-scope-note">正在聚焦：{{ laneName(evidenceFocus) }}<button @click="evidenceFocus=''">恢复全部方向 ↗</button></div>
      <article v-for="entry in focusedEvidence" :key="entry.id" class="report-finding">
        <div class="finding-title"><h4>{{ entry.title }}</h4><span>{{ labelFor(entry.status) }}</span></div>
        <p>{{ entry.finding }}</p>
        <template v-for="(dataset, index) in entry.dataset_results || []" :key="index">
          <p class="dataset-caption">{{ dataset.dataset_name }} · {{ dataset.row_count }} 行 · 按数据集报告口径展示</p>
          <EvidenceChart :dataset="dataset" :renderer="renderChart" :allow-auto="allowAutoChart" />
          <details class="expert-interpretation"><summary>查看专家解读</summary><div class="report-analysis">{{ dataset.analysis }}</div></details>
        </template>
        <button type="button" class="text-action" @click="openEvidence(entry.id)">查看该发现的证据 ↗</button>
      </article>
      <p v-if="result.research.gaps?.length" class="gap-note">待补证：{{ result.research.gaps.join('、') }}</p>
    </section>

    <details v-if="advanced" class="execution-record" :open="!advanced && active">
      <summary><span>{{ advanced ? '研究执行记录' : active ? '正在查询与核验' : '展开查询与核验记录' }}</span><small>{{ nodes.length }} 项真实记录 · {{ advanced ? '42' : '15' }} 节点流程</small></summary>
      <div v-if="!nodes.length" class="empty-record">正在连接任务，尚未收到工具执行记录。</div>
      <ol class="node-list"><li v-for="node in nodes" :key="node.key" :class="node.status"><span class="node-mark">{{ marker(node.status) }}</span><div><strong>{{ node.title }}</strong><span class="node-role">{{ node.role }}<template v-if="node.skill"> · {{ node.skill }}</template><template v-if="node.branch_id"> · {{ laneName(node.branch_id) }}</template></span><p>{{ node.summary }}</p></div><small>{{ labelFor(node.status) }}</small></li></ol>
      <details class="catalog"><summary>完整节点清单 · 未收到事件的节点不标记为完成</summary><div v-for="node in workflow.catalog || []" :key="node.id"><code>{{ node.id }}</code><span>{{ node.title }}</span><small>{{ nodes.some(n => n.node_id === node.id) ? '有执行记录' : '未执行 / 条件未触发' }}</small></div></details>
    </details>

    <aside v-if="selectedEvidence" ref="drawer" class="evidence-drawer" aria-label="证据详情">
      <div class="section-heading"><h3>{{ selectedEvidence.title }} · 依据</h3><button type="button" class="text-action" @click="selectedEvidenceId = ''">收起 ×</button></div>
      <p>{{ selectedEvidence.finding }}</p>
      <p class="muted">组织范围：当前账号授权组织。结果只证明本次查询事实，假设支持程度仍需业务验证。</p>
      <div v-for="(dataset, index) in selectedEvidence.dataset_results || []" :key="index">
        <h4>{{ dataset.dataset_name }}</h4>
        <div class="table-scroll"><table><thead><tr><th v-for="column in dataset.columns" :key="column">{{ column }}</th></tr></thead><tbody><tr v-for="(row, rowIndex) in (dataset.rows || []).slice(0,30)" :key="rowIndex"><td v-for="column in dataset.columns" :key="column">{{ row[column] ?? '—' }}</td></tr></tbody></table></div>
        <small>预览前30行；完整结果沿用报告与下载权限。</small>
        <details v-if="allowTechnical"><summary>SQL 与审核记录</summary><pre>{{ dataset.sql }}</pre><p>{{ dataset.agent3_review?.review_summary }}</p></details>
      </div>
    </aside>
  </section>
</template>
<script setup>
import { computed, ref, watch, nextTick } from 'vue'
import { workflowStages, taskOutcome, analysisPhases } from '../../state/askWorkflow'
import EvidenceChart from './EvidenceChart.vue'
import AnalysisBrief from './AnalysisBrief.vue'
const props = defineProps({ workflow: { type: Object, default: () => ({}) }, result: { type: Object, default: null }, status: { type: String, default: 'idle' }, readonly: Boolean, busy: Boolean, allowTechnical: Boolean, allowDownload: Boolean, renderChart: Function, allowAutoChart: Boolean, allowInspector:Boolean, allowRetry:Boolean })
defineEmits(['start-plan','download-report','inspect','retry'])
const desk = ref(null)
const drawer = ref(null)
const navigate = key => { const target = desk.value?.querySelector('.'+key); if (target) { if (target.tagName === 'DETAILS') target.open = true; target.scrollIntoView({block:'start',behavior:'auto'}) } }
const selected = ref([])
const reportTab = ref('summary')
const selectedEvidenceId = ref('')
const evidenceFocus = ref('')
const plan = computed(() => props.result?.research_plan)
const waiting = computed(() => props.result?.confirmation_type === 'research_plan' && props.result?.requires_confirmation && !props.result?.aborted && props.status !== 'canceled' && !props.busy)
const advanced = computed(() => (props.workflow.flow || props.result?.ask_flow?.flow) === 'advanced')
const active = computed(() => outcome.value.status === 'running')
const evidence = computed(() => props.result?.research?.evidence || props.workflow.evidence || [])
const focusedEvidence = computed(() => evidenceFocus.value ? evidence.value.filter(entry=>entry.id===evidenceFocus.value) : evidence.value)
watch(() => props.workflow.run_id, () => { evidenceFocus.value=''; selectedEvidenceId.value='' })
const lanes = computed(() => props.workflow.branches?.length ? props.workflow.branches : plan.value?.branches || [])
const outcome=computed(()=>taskOutcome(props.result,{status:props.status,busy:props.busy,workflow:props.workflow}))
const phases=computed(()=>analysisPhases(props.workflow,outcome.value.status))
const latestPhase=computed(()=>(phases.value.find(p=>p.status==='running') || [...phases.value].reverse().find(p=>p.nodes.length))?.id || 0)
const nodes = computed(() => workflowStages(props.workflow,outcome.value.status))
const labelFor = (s) => ({ planned:'待派发', running:'执行中', completed:'已完成', success:'已完成', failed:'未完成', insufficient:'证据不足', warning:'需关注', interrupted:'未完成', retrying:'正在修复', waiting:'待确认', canceled:'已停止' }[s] || '待验证')
const marker = s => s === 'completed' || s === 'success' ? '✓' : s === 'running' ? '·' : s === 'failed' ? '!' : '○'
const branchEvidence = id => evidence.value.find(e => e.id === id)
const branchNodes = id => nodes.value.filter(n => n.branch_id === id)
const branchStatus = id => branchEvidence(id)?.status || (branchNodes(id).length ? active.value ? 'running' : 'insufficient' : 'planned')
const latestBranchActivity = id => branchNodes(id).at(-1)?.summary || '等待并发调度'
const laneName = id => lanes.value.find(b => b.id === id)?.title || id
const selectedEvidence = computed(() => evidence.value.find(e => e.id === selectedEvidenceId.value))
const openEvidence = async id => { selectedEvidenceId.value = id; await nextTick(); drawer.value?.scrollIntoView({block:'start',behavior:'auto'}) }
const stateLabel = computed(() => outcome.value.label)
const lifecycle=computed(()=>[
  {name:'研究计划',state:waiting.value?'current':plan.value?'done':'pending',label:waiting.value?'等待你确认':plan.value?'已形成计划':'待规划'},
  {name:'并行取证',state:props.result?.research?'done':active.value && lanes.value.length && !waiting.value?'current':'pending',label:props.result?.research?'已返回证据':active.value && !waiting.value?'取证中':'待派发'},
  {name:'复核与交付',state:props.result?.research?'done':'pending',label:props.result?.research?.partial?'存在待补证项':props.result?.research?'可查看报告':'待证据汇合'}])
watch(() => plan.value?.id, () => { selected.value = (plan.value?.branches || []).map(b => b.id) }, { immediate:true })
</script>
<style scoped>
